import {createLobbyCharacter} from './lobby-character.js?v=1.6.0';
import {ROOMS,STORAGE_KEY,validProgress,requiredCompletedCount,requiredRemaining,isRoomUnlocked,canEnterRoom,canEscape,isRoomOrigin,parseRoomMessage,createDoorTracker} from './mission-state.js?v=1.6.0';
const app=document.getElementById('app');
const lobbyScene='2172808776581645156';
const outsideScene='2172833417257813860';
let solved=[];try{solved=validProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]'));}catch{}
const jumpedRooms=new Set();let jumpInProgress=false,pendingRoomHelp=false;
let view='board',active=null,lastCompleted=null,lastLeft=null,roomFrame=null,lobbyFrame=null,tracker=null,loadTimeout,character=null,controlCleanup=null,explorerHidden=false;
const lock='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>';
const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 12h16M14 6l6 6-6 6"/></svg>';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(solved));}catch{}}
function roomUrl(id){return 'https://www.thinglink.com/view/scene/'+id+'?lang=en&embed=1';}
function progress(){const required=requiredCompletedCount(solved);return '<div class="progress" aria-label="'+solved.length+' '+(solved.length===1?'point':'points')+'; '+required+' of 4 required missions complete"><span class="progress-count">'+solved.length+' <span>'+(solved.length===1?'point':'points')+'</span></span><div class="progress-lights">'+ROOMS.map(r=>'<i class="'+(solved.includes(r.number)?'lit ':'')+(r.optional?'bonus-light':'')+'" title="Room '+r.number+(r.optional?' (optional bonus)':'')+(solved.includes(r.number)?' complete':' remaining')+'"></i>').join('')+'</div><span class="progress-caption">'+required+' / 4 required'+(solved.includes('357')?' + bonus':'')+'</span></div>';}
function roomCard(r){const done=solved.includes(r.number),locked=!isRoomUnlocked(r.number,solved),remaining=Math.max(0,(r.unlockAfter||0)-solved.length);const label=done?(r.optional?'Bonus cleared':'Cleared'):locked?(remaining===1?'1 more point to unlock':remaining+' points to unlock'):r.optional?'Enter bonus':'Enter room';return '<button class="lobby-room '+(done?'is-cleared ':'')+(locked?'is-locked ':'')+(r.optional?'is-bonus':'')+'" data-room="'+r.number+'" '+(!canEnterRoom(r.number,solved)?'disabled':'')+' aria-label="Room '+r.number+', '+r.floor+(r.optional?', optional bonus':'')+', '+label+'"><span class="lobby-room-top">'+r.floor+(r.optional?' · Optional':'')+(done?'<span class="room-tick" aria-hidden="true">✓</span>':locked?lock:arrow)+'</span><strong>'+r.number+'</strong><span class="room-state">'+label+'</span></button>';}
function header(){return '<header class="topbar"><a class="brand" href="#" aria-label="Return to GSE lobby"><span>HAUNTED</span><strong>GSE</strong></a><div class="header-right">'+progress()+(view==='room'?'<button class="text-button" id="board-button" title="Leave this room unsolved and return to the lobby. You can try it again later.">Return to lobby '+arrow+'</button>':'<span class="exit-status '+(canEscape(solved)?'is-open':'')+'">'+lock+(canEscape(solved)?'Exit unlocked':'Exit locked')+'</span>')+'</div></header>';}
function loading(label){return '<div class="room-loading" role="status"><span class="loading-dot"></span><p>'+label+'</p><button id="reload-scene" class="text-button" hidden>Reload scene</button></div>';}
function watchLoading(){loadTimeout=setTimeout(()=>{const el=document.querySelector('.room-loading');if(el){el.querySelector('p').textContent='The scene is taking a moment to load.';document.getElementById('reload-scene').hidden=false;}},18000);document.getElementById('reload-scene').onclick=render;}
function render(){controlCleanup?.();controlCleanup=null;character?.dispose();character=null;clearTimeout(loadTimeout);roomFrame=null;lobbyFrame=null;tracker=null;app.className='view-'+view;
if(view==='room'){
app.innerHTML=header()+'<main class="room-stage"><div class="room-label"><span>MISSION</span><h1>Room '+active.number+'</h1></div>'+loading('Entering Room '+active.number+'…')+'<iframe id="mission-room" title="Room '+active.number+' puzzle" src="'+roomUrl(active.scene)+'" allow="autoplay"></iframe></main>';
roomFrame=document.getElementById('mission-room');tracker=createDoorTracker(active);watchLoading();document.getElementById('board-button').onclick=leaveRoom;mountRoomHelp();
}else if(view==='finish'){
app.innerHTML='<iframe class="backdrop" title="Outside Penn GSE" tabindex="-1" aria-hidden="true" src="'+roomUrl(outsideScene)+'"></iframe><div class="shade"></div>'+header()+'<main class="finish content-enter"><div class="eyebrow">OUTSIDE PENN GSE</div><div class="escape-mark">'+arrow+'</div><h1>You made<br>it out.</h1><p>You step outside onto Walnut Street. All four required rooms are clear, and you have escaped Haunted GSE. Congratulations!'+(solved.includes('357')?' You cleared the bonus room, too!':'')+'</p><div class="finished-rooms">'+ROOMS.filter(r=>!r.optional||solved.includes(r.number)).map(r=>'<span>✓ '+r.number+(r.optional?' · bonus':'')+'</span>').join('')+'</div></main>';

}else{
const left=requiredRemaining(solved),allDone=canEscape(solved);
const notice=allDone?'The four required rooms are clear. The main exit is open. Room 357 is an optional bonus.':lastCompleted?'Room '+lastCompleted+' cleared. Choose your next mission.':lastLeft?'Room '+lastLeft+' is still unsolved. Try another room, or return to it later.':'Clear four required rooms to open the exit. Optional Room 357 unlocks after you earn 2 points.';
app.innerHTML=header()+'<main class="lobby-stage"><iframe id="lobby-scene" title="GSE study-room lobby" tabindex="-1" src="'+roomUrl(lobbyScene)+'" allow="autoplay"></iframe>'+'<div id="lobby-character" class="lobby-character" aria-hidden="true"></div>'+loading('Entering the GSE lobby…')+'<section class="lobby-welcome content-enter"><span class="eyebrow">YOUR ESCAPE STARTS HERE</span><h1>Study-room lobby</h1><p id="lobby-notice" role="status">'+notice+'</p><span class="lobby-look">Use the arrow keys or drag the explorer to walk. Choose a room from the directory.</span></section><section class="lobby-directory" aria-label="Lobby room directory"><div class="directory-heading"><div><span class="eyebrow">ROOM DIRECTORY</span><h2>'+(allDone?(solved.includes('357')?'All rooms complete':'Required rooms complete'):'Choose your next room')+'</h2></div><button class="text-button" id="toggle-directory" aria-expanded="true" aria-controls="directory-options">Hide directory</button></div><div id="directory-options"><div class="lobby-rooms">'+ROOMS.map(roomCard).join('')+'</div><div class="directory-bottom"><span>10 minutes · Follow the presentation timer.</span><div class="lobby-exit"><span>'+(allDone?'Ready to escape':left.length+' required '+(left.length===1?'room':'rooms')+' remaining')+'</span><button id="escape" class="primary '+(allDone?'':'locked')+'" '+(allDone?'':'disabled')+'>'+(allDone?'Leave GSE '+arrow:lock+' Main exit locked')+'</button></div></div></div></section><button class="lobby-reset text-button" id="new-attempt">New attempt</button></main>';
lobbyFrame=document.getElementById('lobby-scene');character=createLobbyCharacter(document.getElementById('lobby-character'),{position:[.48,.88],onReady:()=>{if(view!=='board')return;clearTimeout(loadTimeout);document.querySelector('.room-loading')?.remove();document.getElementById('lobby-scene')?.remove();lobbyFrame=null;}});mountCompanionControls(document.querySelector('.lobby-stage'));addRoomTools(document.querySelector('.lobby-stage'));watchLoading();app.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>enterRoom(b.dataset.room));document.getElementById('escape').onclick=()=>{if(canEscape(solved)){view='finish';lastCompleted=null;render()}};document.getElementById('new-attempt').onclick=newAttempt;
document.getElementById('toggle-directory').onclick=()=>{const button=document.getElementById('toggle-directory'),options=document.getElementById('directory-options');options.hidden=!options.hidden;button.setAttribute('aria-expanded',String(!options.hidden));button.textContent=options.hidden?'Choose a room':'Hide directory';};
}
app.querySelector('.brand').onclick=e=>{e.preventDefault();if(view==='room')leaveRoom();else if(view==='finish'){view='board';render()}};
}
function leaveRoom(){lastLeft=active?.number??null;view='board';active=null;lastCompleted=null;render();}
function addRoomTools(stage){
const lobby=stage.classList.contains('lobby-stage'),tools=document.createElement('div');tools.className='room-tools';tools.innerHTML='<button class="text-button" id="room-controls">How to explore</button>'+(lobby?'<button class="text-button" id="toggle-explorer">'+(explorerHidden?'Show explorer':'Hide explorer')+'</button>':'');
if(lobby){tools.classList.add('lobby-help-tools');stage.querySelector('.lobby-welcome').append(tools);}else stage.append(tools);
document.getElementById('room-controls').onclick=showRoomControls;
if(lobby)document.getElementById('toggle-explorer').onclick=()=>{explorerHidden=!explorerHidden;character?.visible(!explorerHidden);stage.classList.toggle('explorer-hidden',explorerHidden);document.getElementById('toggle-explorer').textContent=explorerHidden?'Show explorer':'Hide explorer';};
}
function mountRoomHelp(){
addRoomTools(document.querySelector('.room-stage'));let seen=false;try{seen=sessionStorage.getItem('gse-room-controls-seen')==='yes';}catch{}if(!seen){if(jumpInProgress)pendingRoomHelp=true;else showRoomControls();}
}
function mountCompanionControls(stage){
if(!character)return;const char=character,drag=document.createElement('button');drag.className='explorer-drag';drag.setAttribute('aria-label','Drag explorer to walk around the lobby');drag.title='Drag to walk. Arrow keys also move the explorer.';stage.append(drag);
const controls=document.createElement('div');controls.className='explorer-controls';controls.setAttribute('role','group');controls.setAttribute('aria-label','Move explorer');controls.innerHTML='<span>ARROW KEYS TO WALK</span><div class="explorer-pad"><button data-x="0" data-y="-1" aria-label="Move explorer up">↑</button><button data-x="-1" data-y="0" aria-label="Move explorer left">←</button><button data-x="1" data-y="0" aria-label="Move explorer right">→</button><button data-x="0" data-y="1" aria-label="Move explorer down">↓</button></div>';stage.append(controls);
char.listen((p,moving)=>{drag.style.left=(p[0]*100)+'%';drag.style.top=(p[1]*100)+'%';drag.dataset.moving=String(moving);});
let captured=false,offset=[0,0],lastPlan=0;const held=new Set();
const stop=()=>{held.clear();char.stop();};
const point=e=>{const r=stage.getBoundingClientRect();char.target([(e.clientX-offset[0]-r.left)/r.width,(e.clientY-offset[1]-r.top)/r.height]);};
drag.onpointerdown=e=>{e.preventDefault();held.clear();const r=drag.getBoundingClientRect();offset=[e.clientX-r.left-r.width/2,e.clientY-r.bottom];captured=true;drag.setPointerCapture(e.pointerId);};
drag.onpointermove=e=>{if(captured&&performance.now()-lastPlan>70){lastPlan=performance.now();point(e);}};drag.onpointerup=e=>{if(captured)point(e);captured=false;};drag.onpointercancel=()=>{captured=false;stop();};
controls.querySelectorAll('button').forEach(button=>{let start=0;button.onpointerdown=e=>{if(explorerHidden||document.querySelector('dialog[open]'))return;e.preventDefault();held.clear();start=performance.now();button.setPointerCapture(e.pointerId);char.direction(Number(button.dataset.x),Number(button.dataset.y));};button.onpointerup=()=>{char.direction(0,0);};button.onpointercancel=stop;button.onclick=e=>{if(explorerHidden)return;if(e.detail===0||performance.now()-start<170){const p=[parseFloat(drag.style.left)/100,parseFloat(drag.style.top)/100];char.target([p[0]+Number(button.dataset.x)*.06,p[1]+Number(button.dataset.y)*.08]);}};});
const keys={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]};
const update=()=>{let x=0,y=0;for(const key of held){x+=keys[key][0];y+=keys[key][1];}char.direction(Math.sign(x),Math.sign(y));};
const keydown=e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(!keys[key]||view!=='board'||explorerHidden||e.metaKey||e.ctrlKey||e.altKey||e.target.closest?.('input,textarea,select,[contenteditable="true"]')||document.querySelector('dialog[open]'))return;e.preventDefault();held.add(key);update();};
const keyup=e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(!held.has(key))return;e.preventDefault();held.delete(key);update();};
const pauseForDialog=e=>{if(e.target.closest?.('#room-controls,#toggle-explorer,#new-attempt'))stop();};
window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',stop);document.addEventListener('visibilitychange',stop);stage.addEventListener('click',pauseForDialog);
controlCleanup=()=>{char.listen(null);stop();window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',stop);document.removeEventListener('visibilitychange',stop);stage.removeEventListener('click',pauseForDialog);drag.remove();controls.remove();};
stage.classList.toggle('explorer-hidden',explorerHidden);char.visible(!explorerHidden);
}
function showRoomControls(){
if(document.querySelector('.room-guide'))return;const lobbyGuide=view==='board';const dialog=document.createElement('dialog');dialog.className='room-guide';dialog.setAttribute('aria-labelledby','guide-title');dialog.innerHTML=view==='board'?'<span class="eyebrow">LOBBY CONTROLS</span><h2 id="guide-title">Walk around the lobby</h2><ol><li><strong>Move the explorer.</strong> Hold the arrow keys or W, A, S, D. You can also hold the on-screen arrows.</li><li><strong>Choose a destination.</strong> Drag the explorer to a spot on the floor. It will walk around the sofa to reach it.</li><li><strong>Enter a room.</strong> Choose its number from the room directory.</li></ol><p class="guide-note">The lobby view stays fixed so furniture and walls line up with the walking area. Each puzzle room has its own 360° controls.</p><button class="primary" id="close-guide">Got it '+arrow+'</button>':'<span class="eyebrow">ROOM CONTROLS</span><h2 id="guide-title">Explore the room</h2><ol><li><strong>Look around.</strong> Click and drag the background. On a phone, swipe with one finger.</li><li><strong>Zoom in.</strong> Use your mouse wheel or pinch with two fingers.</li><li><strong>Open clues.</strong> Click the markers. Close the panel when you want to keep exploring.</li><li><strong>Unlock the door.</strong> Open its marker and enter your answer when you are ready.</li><li><strong>Return to the lobby.</strong> Use Return to lobby whenever you want to leave the room.</li></ol><p class="guide-note">Dragging the background turns your view. Furniture and other objects in the photo cannot be picked up.</p><button class="primary" id="close-guide">Got it '+arrow+'</button>' ;document.body.append(dialog);dialog.showModal();dialog.querySelector('#close-guide').onclick=()=>dialog.close();dialog.onclose=()=>{if(!lobbyGuide)try{sessionStorage.setItem('gse-room-controls-seen','yes')}catch{}dialog.remove();};
}
function enterRoom(number){
 const room=ROOMS.find(r=>r.number===number);if(jumpInProgress||!room||!canEnterRoom(number,solved))return;
 let shot=null,stage=document.querySelector('.lobby-stage');
 if(view==='board'&&!jumpedRooms.has(number)&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&character&&stage){try{shot=character.snapshots();}catch{}}
 jumpedRooms.add(number);let overlay=null,rect=null;
 if(shot){rect=stage.getBoundingClientRect();overlay=document.createElement('div');overlay.className='room-jump';overlay.setAttribute('aria-hidden','true');overlay.style.top=rect.top+'px';overlay.style.height=rect.height+'px';const background=new Image(),explorer=new Image();background.className='jump-background';explorer.className='jump-explorer';background.src=shot.background;explorer.src=shot.explorer;explorer.style.transformOrigin=(shot.position[0]*100)+'% '+(shot.position[1]*100)+'%';overlay.append(background,explorer);document.body.append(overlay);jumpInProgress=true;}
 active=room;lastCompleted=null;lastLeft=null;view='room';render();
 if(!overlay)return;
 const dx=(.5-shot.position[0])*rect.width,dy=(.24-shot.position[1])*rect.height;
 const background=overlay.querySelector('.jump-background'),explorer=overlay.querySelector('.jump-explorer');
 const flight=explorer.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:'translate('+dx*.40+'px,'+(dy*.62-45)+'px) scale(.70) rotate(-8deg)',opacity:1,offset:.45},{transform:'translate('+dx+'px,'+dy+'px) scale(.12) rotate(4deg)',opacity:0}],{duration:620,easing:'cubic-bezier(.22,.65,.3,1)',fill:'forwards'});
 const backdrop=background.animate([{transform:'scale(1)',opacity:1},{transform:'scale(1.045)',opacity:.92,offset:.35},{transform:'scale(1.12)',opacity:0}],{duration:620,easing:'ease-in',fill:'forwards'});
 Promise.allSettled([flight.finished,backdrop.finished]).then(()=>{overlay.remove();jumpInProgress=false;const help=pendingRoomHelp;pendingRoomHelp=false;if(help&&view==='room'&&active?.number===number)showRoomControls();});
}
function newAttempt(){const dialog=document.createElement('dialog');dialog.className='reset-dialog';dialog.innerHTML='<h2>Start a new escape?</h2><p>This clears the completed missions on this browser.</p><div><button class="text-button" id="keep-progress">Keep my progress</button><button class="primary" id="reset-progress">Start again</button></div>';document.body.append(dialog);dialog.showModal();dialog.querySelector('#keep-progress').onclick=()=>dialog.close();dialog.querySelector('#reset-progress').onclick=()=>{solved=[];save();jumpedRooms.clear();active=null;lastCompleted=null;lastLeft=null;view='board';dialog.close();render()};dialog.onclose=()=>dialog.remove();}
function sceneViewed(m,id){return (m.action==='scene.view'&&String(m.sceneId)===id)||(m.action==='TL_STAT'&&m.event==='scene.view'&&String(m.scene?.id)===id);}
window.addEventListener('message',event=>{
if(!isRoomOrigin(event.origin))return;const message=parseRoomMessage(event.data);if(!message)return;
if(view==='board'&&lobbyFrame&&event.source===lobbyFrame.contentWindow){if(sceneViewed(message,lobbyScene)){clearTimeout(loadTimeout);document.querySelector('.room-loading')?.remove();}return;}
if(view!=='room'||!active||!roomFrame||event.source!==roomFrame.contentWindow)return;
const bonus=ROOMS.find(r=>r.optional);if(active.number!==bonus.number&&sceneViewed(message,bonus.scene)){if(canEnterRoom(bonus.number,solved))enterRoom(bonus.number);else{leaveRoom();document.getElementById('lobby-notice').textContent=solved.includes(bonus.number)?'The bonus room is already cleared. Choose another mission.':'Room 357 is locked until you earn 2 points. Complete another required room first.';}return;}
if(sceneViewed(message,active.scene)){clearTimeout(loadTimeout);document.querySelector('.room-loading')?.remove();}
if(active.optional&&!isRoomUnlocked(active.number,solved))return;
if(tracker.observe(message)){const completed=active.number;solved=validProgress([...solved,completed]);save();lastCompleted=completed;lastLeft=null;active=null;view='board';render();}
});
render();
